  lvl({"id":"hc-3","order":45,"topic":"reasoning","skill":"ratio","band":"adventurer","scene":"picnic","title":{"en":"Ratio Recipes","ms":"Resipi Nisbah"},"story":{"en":"The city bakery follows secret recipes made of ratios. Help the baker keep every mix just right!","ms":"Kedai roti bandar mengikut resipi rahsia yang dibuat daripada nisbah. Bantu tukang roti memastikan setiap adunan tepat!"},"learn":{"en":"Use ratios to scale a recipe up.","ms":"Menggunakan nisbah untuk membesarkan sukatan resipi."},"critter":{"id":"doughyhc","name":{"en":"Doughy","ms":"Doughy"},"blurb":{"en":"Doughy rises whenever the ratio is right.","ms":"Doughy naik apabila nisbahnya betul."},"look":{"body":"blob","c1":"#fff3a8","c2":"#ffd84d","ears":"leaf","feat":"fin","acc":"none"}},"tiers":[{"id":"hc-3-a","type":"steps","prompt":{"en":"Solve each step in order.","ms":"Selesaikan setiap langkah mengikut urutan."},"hint":{"en":"A ratio of 2 : 1 means the flour is double the sugar.","ms":"Nisbah 2 : 1 bermaksud tepung dua kali ganda gula."},"explain":{"en":"6 ÷ 2 = 3 cups of sugar, then 6 + 3 = 9 cups, then 9 ÷ 3 = 3 cups in each jar.","ms":"6 ÷ 2 = 3 cawan gula, kemudian 6 + 3 = 9 cawan, kemudian 9 ÷ 3 = 3 cawan dalam setiap balang."},"spec":{"steps":[{"q":{"en":"A recipe uses 2 cups of flour for every 1 cup of sugar. How much sugar for 6 cups of flour?","ms":"Satu resipi menggunakan 2 cawan tepung untuk setiap 1 cawan gula. Berapa cawan gula untuk 6 cawan tepung?"},"choices":["3","103","6","2"],"answer":0,"calc":"6/2"},{"q":{"en":"How many cups are there altogether?","ms":"Berapa cawan kesemuanya?"},"choices":["9","11","4","10"],"answer":0,"calc":"6+3"},{"q":{"en":"The mix is poured equally into 3 jars. How many cups in each jar?","ms":"Adunan dituang sama banyak ke dalam 3 balang. Berapa cawan dalam setiap balang?"},"choices":["1","8","3","6"],"answer":2,"calc":"9/3"}]}},{"id":"hc-3-b","type":"steps","prompt":{"en":"Solve each step in order.","ms":"Selesaikan setiap langkah mengikut urutan."},"hint":{"en":"Find how many groups of 3 are in 12.","ms":"Cari berapa kumpulan 3 dalam 12."},"explain":{"en":"12 ÷ 3 = 4 groups, so blue is 4 × 2 = 8. Then 12 + 8 = 20, then 20 ÷ 4 = 5.","ms":"12 ÷ 3 = 4 kumpulan, jadi biru ialah 4 × 2 = 8. Kemudian 12 + 8 = 20, kemudian 20 ÷ 4 = 5."},"spec":{"steps":[{"q":{"en":"A paint mix uses 3 parts red for every 2 parts blue. How many parts of blue for 12 parts of red?","ms":"Satu adunan cat menggunakan 3 bahagian merah untuk setiap 2 bahagian biru. Berapa bahagian biru untuk 12 bahagian merah?"},"choices":["8","3","7","13"],"answer":0,"calc":"12/3*2"},{"q":{"en":"How many parts of paint is that altogether?","ms":"Berapa bahagian cat kesemuanya?"},"choices":["19","120","10","20"],"answer":3,"calc":"12+8"},{"q":{"en":"The paint is shared equally into 4 tins. How many parts in each tin?","ms":"Cat itu dikongsi sama banyak ke dalam 4 tin. Berapa bahagian dalam setiap tin?"},"choices":["7","3","4","5"],"answer":3,"calc":"20/4"}]}},{"id":"hc-3-c","type":"steps","prompt":{"en":"Solve each step in order.","ms":"Selesaikan setiap langkah mengikut urutan."},"hint":{"en":"How many groups of 5 are in 40?","ms":"Berapa kumpulan 5 dalam 40?"},"explain":{"en":"40 ÷ 5 = 8 groups, so apple is 8 × 3 = 24. Then 40 + 24 = 64, then 64 ÷ 8 = 8.","ms":"40 ÷ 5 = 8 kumpulan, jadi epal ialah 8 × 3 = 24. Kemudian 40 + 24 = 64, kemudian 64 ÷ 8 = 8."},"spec":{"steps":[{"q":{"en":"Juice is 5 parts orange to 3 parts apple. How many parts of apple go with 40 parts of orange?","ms":"Jus itu 5 bahagian oren kepada 3 bahagian epal. Berapa bahagian epal bersama 40 bahagian oren?"},"choices":["29","12","25","24"],"answer":3,"calc":"40/5*3"},{"q":{"en":"How many parts of juice are there altogether?","ms":"Berapa bahagian jus kesemuanya?"},"choices":["59","64","65","128"],"answer":1,"calc":"40+24"},{"q":{"en":"The juice is poured equally into 8 bottles. How many parts in each bottle?","ms":"Jus itu dituang sama banyak ke dalam 8 botol. Berapa bahagian dalam setiap botol?"},"choices":["3","18","10","8"],"answer":3,"calc":"64/8"}]}}]});
